const input = Array.isArray($json) ? $json : [$json];
return input.map((record) => {
  const days = Number(record.lastTouchDays ?? 0);
  const canContact = record.contactAllowed === true;
  let nextAction = 'Do not contact.';
  if (canContact && record.status === 'no-show') nextAction = days >= 1 ? 'Send approved reschedule follow-up.' : 'Create same-day office callback task.';
  if (canContact && record.status === 'late cancellation') nextAction = 'Add to short-notice reschedule queue.';
  return { json: { ...record, nextAction } };
});
